#
# Sphinx configuration of the nvme-cli guide, the documentation on
# https://nvme-cli.readthedocs.io. The man pages are not built here:
# their HTML is generated by 'meson compile update-docs' and copied next
# to the guide pages.

import glob
import os
import re

here = os.path.dirname(os.path.abspath(__file__))

with open(os.path.join(here, '..', '..', 'meson.build')) as f:
    m = re.search(r"^\s*version:\s*'([^']+)'", f.read(), re.MULTILINE)
    release = m.group(1) if m else ''
version = release

project = 'nvme-cli'
copyright = 'the nvme-cli contributors'
author = 'the nvme-cli contributors'

extensions = ['myst_parser']
source_suffix = {'.md': 'markdown'}
exclude_patterns = ['_build']
root_doc = 'index'

# GitHub style anchors for headings, e.g. [x](tls.md#configuring-the-target)
myst_heading_anchors = 4
myst_enable_extensions = ['deflist']

# [nvme-connect(1)](man:nvme-connect) links the HTML man page.
myst_url_schemes = {
    'http': None,
    'https': None,
    'mailto': None,
    'man': '{{path}}.html',
}

html_theme = 'sphinx_rtd_theme'
html_title = f'nvme-cli {release}'
html_theme_options = {
    'collapse_navigation': False,
    'navigation_depth': 2,
    'style_external_links': True,
}
# The "Edit on GitHub" link of each page.
html_context = {
    'display_github': True,
    'github_user': 'linux-nvme',
    'github_repo': 'nvme-cli',
    'github_version': 'master',
    'conf_py_path': '/Documentation/guide/',
}
html_copy_source = False
html_show_sourcelink = False

# The man pages, generated by 'meson compile update-docs'.
html_extra_path = sorted(os.path.relpath(p, here)
                         for p in glob.glob(os.path.join(here, '..', '*.html')))


# commands.md gets the lists of man pages, generated from the lists the
# man page nvme(1) includes and from Documentation/meson.build.
def man_list(name):
    with open(os.path.join(here, '..', name)) as f:
        pages = re.findall(r'^linknvme:([^\[]+)\[(\d)\]::\n\s+(.*)$',
                           f.read(), re.MULTILINE)
    rows = ['| Man page | Description |', '|---|---|']
    for p, s, d in pages:
        d = d.replace('|', '\\|')
        rows.append(f'| [{p}({s})](man:{p}) | {d} |')
    return '\n'.join(rows)


def man_section(section):
    with open(os.path.join(here, '..', 'meson.build')) as f:
        m = re.search(rf'^adoc_sources_man{section} = \[(.*?)\]', f.read(),
                      re.MULTILINE | re.DOTALL)
    pages = re.findall(r"'([^']+)'", m.group(1)) if m else []
    return '\n'.join(f'- [{p}({section})](man:{p})' for p in pages)


def fill_commands(app, docname, source):
    if docname != 'commands':
        return
    for key, text in (('main', lambda: man_list('cmds-main.txt')),
                      ('plugins', lambda: man_list('cmd-plugins.txt')),
                      ('man5', lambda: man_section(5)),
                      ('man8', lambda: man_section(8))):
        source[0] = source[0].replace(f'@{key}@', text())


def setup(app):
    app.connect('source-read', fill_commands)
